import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { predictionAPI } from "../services/api";

const INITIAL = {
  gender: "", age: "", hypertension: "", heart_disease: "",
  ever_married: "", work_type: "", residence_type: "",
  avg_glucose_level: "", bmi: "", smoking_status: "",
};

export default function PredictPage() {
  const [form, setForm] = useState(INITIAL);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const { data } = await predictionAPI.submit(form);
      navigate("/patient/result", { state: { result: data.result, probability: data.probability, inputData: form } });
    } catch (err) {
      setError(err.response?.data?.message || "Prediction failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const Field = ({ label, name, children }) => (
    <div className="form-group">
      <label>{label}</label>
      {children || (
        <input className="form-control" name={name} value={form[name]} onChange={handleChange} required />
      )}
    </div>
  );

  const Select = ({ label, name, options }) => (
    <Field label={label} name={name}>
      <select className="form-control" name={name} value={form[name]} onChange={handleChange} required>
        <option value="">Select…</option>
        {options.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
      </select>
    </Field>
  );

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <div style={{ maxWidth: 700, margin: "0 auto" }}>
          <h1 style={{ fontSize: "1.5rem", fontWeight: 700, marginBottom: ".3rem" }}>Stroke Risk Assessment</h1>
          <p style={{ color: "var(--text-muted)", marginBottom: "1.5rem", fontSize: ".9rem" }}>
            Fill in your health details below. The ML model will analyse your risk level.
          </p>

          {error && <div className="alert alert-error">{error}</div>}

          <div className="card">
            <form onSubmit={handleSubmit}>
              <h4 style={{ marginBottom: "1rem", color: "var(--text-muted)", fontSize: ".85rem", textTransform: "uppercase", letterSpacing: ".06em" }}>Personal Information</h4>
              <div className="form-row">
                <Select label="Gender" name="gender" options={[["male","Male"],["female","Female"],["other","Other"]]} />
                <Field label="Age">
                  <input className="form-control" type="number" name="age" min={0} max={120} value={form.age} onChange={handleChange} required />
                </Field>
              </div>
              <div className="form-row">
                <Select label="Ever Married?" name="ever_married" options={[["yes","Yes"],["no","No"]]} />
                <Select label="Work Type" name="work_type" options={[
                  ["Private","Private"],["Self-employed","Self-employed"],
                  ["Government job","Government Job"],["Children","Children"],["Never Worked","Never Worked"]
                ]} />
              </div>
              <Select label="Residence Type" name="residence_type" options={[["urban","Urban"],["rural","Rural"]]} />

              <hr style={{ margin: "1.2rem 0", borderColor: "var(--border)" }} />
              <h4 style={{ marginBottom: "1rem", color: "var(--text-muted)", fontSize: ".85rem", textTransform: "uppercase", letterSpacing: ".06em" }}>Medical Information</h4>

              <div className="form-row">
                <Select label="Hypertension" name="hypertension" options={[["1","Yes"],["0","No"]]} />
                <Select label="Heart Disease" name="heart_disease" options={[["1","Yes"],["0","No"]]} />
              </div>
              <div className="form-row">
                <Field label="Average Glucose Level (mg/dL)">
                  <input className="form-control" type="number" step="0.01" name="avg_glucose_level" min={50} max={400} value={form.avg_glucose_level} onChange={handleChange} required />
                </Field>
                <Field label="BMI">
                  <input className="form-control" type="number" step="0.1" name="bmi" min={10} max={60} value={form.bmi} onChange={handleChange} required />
                </Field>
              </div>
              <Select label="Smoking Status" name="smoking_status" options={[
                ["never smoked","Never Smoked"],["formerly smoked","Formerly Smoked"],
                ["smokes","Smokes"],["unknown","Unknown"]
              ]} />

              <button className="btn btn-primary btn-block" type="submit" disabled={loading} style={{ marginTop: "1rem" }}>
                {loading ? <><span className="spinner"></span> Analysing… (ML model running)</> : "🔍 Predict Stroke Risk"}
              </button>
            </form>
          </div>

          <div className="alert alert-warning" style={{ marginTop: "1rem", fontSize: ".85rem" }}>
            ⚠️ This tool is for informational purposes only and does not constitute medical advice.
          </div>
        </div>
      </main>
    </div>
  );
}
